import { $, $$, dateLabel, isoToday, researchPapers, state, persist, app, toast, roleName, user, userAvatar, svg, esc, fmtDate, sessionMedia } from './core.js';
import { enterPage, animateSelection } from './motion.js';
import { communityPage as communityApplicationPage } from './community.js';
import { workspaceSidebar } from './navigation.js';
import { healthPage } from './health.js';
const webAssets=Object.fromEntries(Object.entries(import.meta.glob('/assets/WEB assets/*.{jpg,jpeg,png,webp,webm}',{eager:true,query:'?url',import:'default'})).map(([path,url])=>[path.split('/').pop(),url]));
const webAsset=filename=>webAssets[filename]||'';
// Revert to the original still portrait by setting this flag to false.
const ENABLE_LANDING_HERO_VIDEO=false;
const landingHeroVideoEnabled=()=>ENABLE_LANDING_HERO_VIDEO&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const landingHeroArtwork=()=>{
  const sculpture='<img class="hero-sculpture" src="'+webAsset('R7V6IVGlqfccFYXQd_Yu7JuZNTAzZknlBqAXUvr7VD4qqHMGJWACNPpi2aGjIbvpdN4U2nAziuWknqP61OAAdNGoajS2aJInvqm9I-s-wlxRQT6g51dWb6xadGO3Gq3wXWxbCDgQKskBCgwYtt4JB0NuY9llBS4UaZSwdk9I5acj0ZpHZNlatQXZppFPnuw9.jpg')+'" alt="Translucent, sculptural forms in warm rose and violet" fetchpriority="high" />';
  const still='<div class="portrait-frame"><img src="'+webAsset('jjiPzrY2i0E9mf36RYx0TxvOrG-V2yCKuMzFUitacCiWrsyeABfwvKf8poZeAH5xKGNshBDSWyNsynKwq20jFfIQqSM6aPbPzKHKaamxWRau55jlO-aSy8TcKb7OiC1rsRlKlJjWw2U8qciaX3KsU2vjDNbh4jH7IfaZXb7Sc1ofjrqWAo8IkyIBtr9Bdm2s.jpg')+'" alt="A woman doctor looking ahead" /></div>';
  if(!landingHeroVideoEnabled())return sculpture+still;
  return '<video class="hero-video-backdrop" autoplay muted loop playsinline preload="metadata" poster="'+webAsset('jjiPzrY2i0E9mf36RYx0TxvOrG-V2yCKuMzFUitacCiWrsyeABfwvKf8poZeAH5xKGNshBDSWyNsynKwq20jFfIQqSM6aPbPzKHKaamxWRau55jlO-aSy8TcKb7OiC1rsRlKlJjWw2U8qciaX3KsU2vjDNbh4jH7IfaZXb7Sc1ofjrqWAo8IkyIBtr9Bdm2s.jpg')+'" aria-hidden="true"><source src="'+webAsset('Animate the woman in the uploade 881281 IF1.webm')+'" type="video/webm" /></video><div class="hero-video-blend" aria-hidden="true"></div>';
};
const routeTitles={dashboard:'Home','my-health':'My health','health-journal':'Journal','health-insights':'Insights','health-records':'Records','health-conversation':'Mira','talk-to-mira':'Talk to Mira',care:'Find care',research:'Research hub',matches:'Research matches',discover:'Discover',community:'Community',timeline:'Health timeline',records:'Medical records',medications:'Treatments',reports:'Consultation reports',professional:'Professional workspace',profile:'Profile',verification:'Credential verification',admin:'Admin overview',moderation:'Community moderation',notifications:'Notifications',settings:'Privacy & settings'};
function topbar(route=state.route){const searchPlaceholder=user().role==='doctor'?'Search appointments & patients':user().role==='researcher'?'Search publications & topics':'Search your health space';return `<header class="topbar"><div class="breadcrumb">Workspace <span style="padding:0 6px;color:#c2c1c0">/</span><strong>${esc(routeTitles[route]||'Home')}</strong></div>${user().demo?'<span class="demo-chip">Sample workspace</span>':''}<div class="top-grow"></div><label class="global-search">${svg('search',15)}<input id="global-search" placeholder="${searchPlaceholder}" aria-label="Search" /></label><button class="round-btn" data-route="notifications" aria-label="Notifications">${svg('bell',16)}${state.notifications.some(n=>!n.read)?'<i class="ping"></i>':''}</button>${userAvatar()}</header>`}
const welcomeIcon = `<span class="flower-art" aria-hidden="true"><span class="flower-ring"></span><span class="flower-ring r2"></span><span class="bloom-spark one">✳</span><span class="bloom-spark two">✦</span><span class="bloom"><i></i><i></i><i></i><i></i><i></i><i></i><b></b></span></span>`;
function pageHeading(title,subtitle,actions=''){const contextual=['care','research','matches','discover'].includes(state.route)?contextTabs(state.route,discoverTabs):['my-health','timeline','records','medications','reports'].includes(state.route)?contextTabs(state.route,healthTabs):'';return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>${contextual}`}
const addButton = (label='Log a symptom',action='log-symptom') => `<button class="btn primary" data-action="${action}">${svg('plus',14)}${label}</button>`;
function graph(){return `<div class="chart-wrap"><div class="chart-y"><span>High</span><span>Moderate</span><span>Low</span></div><svg viewBox="0 0 570 115" preserveAspectRatio="none" role="img" aria-label="Symptom and energy notes across the past month"><defs><linearGradient id="graphFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#a587ac" stop-opacity=".18"/><stop offset="1" stop-color="#a587ac" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 12H570M0 51H570M0 90H570"/><path class="chart-area" d="M0 67 C28 62 32 77 57 71 S92 48 114 53 S148 68 171 62 S205 28 228 39 S260 56 285 50 S320 57 342 41 S375 33 399 47 S430 59 456 45 S486 27 513 36 S546 49 570 30V108H0Z"/><path class="chart-line" d="M0 67 C28 62 32 77 57 71 S92 48 114 53 S148 68 171 62 S205 28 228 39 S260 56 285 50 S320 57 342 41 S375 33 399 47 S430 59 456 45 S486 27 513 36 S546 49 570 30"/><path class="chart-secondary" d="M0 31 C25 40 34 49 57 43 S88 62 114 60 S147 43 171 49 S204 69 228 60 S260 42 285 56 S318 72 342 66 S377 52 399 62 S430 77 456 69 S486 58 513 64 S546 75 570 68"/><circle class="chart-point" cx="228" cy="39" r="3.4"/><circle class="chart-point" cx="456" cy="45" r="3.4"/></svg><div class="chart-x"><span>Oct 06</span><span>Oct 13</span><span>Oct 20</span><span>Oct 27</span><span>${dateLabel}</span></div></div>`}
function dashboard(){
  const who=user(), patient=who.role==='patient';
  if(!patient&&who.role==='doctor')return `${doctorDashboard()}<section class="dashboard-grid doctor-tools"><article class="card"><div class="card-head"><h2>Appointments</h2><span class="status-tag preprint">Preview</span></div>${emptyState('No appointments yet','Appointment requests appear here when a secure booking service is connected.')}</article><article class="card"><div class="card-head"><h2>Patient management</h2></div>${emptyState('No patient relationships','Patients remain private until they choose to connect and share information.')}</article><article class="card"><div class="card-head"><h2>Shared records & history</h2></div>${emptyState('No records shared','View consented records and follow-up history here. This preview stores no clinical data.')}</article></section>`;
  if(!patient&&who.role==='researcher')return `${researcherDashboard()}<section class="dashboard-grid researcher-tools"><article class="card"><div class="card-head"><h2>Study notebook</h2></div>${emptyState('No study notes yet','Draft evidence summaries and limitations alongside your publications.')}</article><article class="card"><div class="card-head"><h2>Collaborations</h2></div>${emptyState('No collaboration requests','Researcher connections and study enquiries will appear here.')}</article></section>`;
  if(!patient&&who.role==='explorer')return explorerDashboard();
  const circles=[['Endometriosis support','Endo','tone-rose'],['Menstrual health','Cycle','tone-lav'],['Living with chronic pain','Pain','tone-sage'],['Women’s health questions','Ask','tone-blue']];
  return `<div class="home-feed"><header class="home-greeting"><div><span class="overline">YOUR SPACE</span><h1>Good morning, ${esc((who.name||'friend').split(' ')[0])}</h1><p>A little room to check in, learn and connect.</p></div><button class="home-profile" data-route="profile" aria-label="Open profile">${userAvatar()}</button></header><section class="home-stories"><div class="section-kicker"><h2>Spaces for you</h2><button class="text-link" data-route="community">See all</button></div><div class="story-rail"><button class="story-item" data-action="log-symptom"><span class="story-orb add">${svg('plus',18)}</span><span>Check in</span></button>${circles.map(([name,label,tone])=>`<button class="story-item" data-route="community" title="Explore ${esc(name)}"><span class="story-orb ${tone}"><span>${label}</span></span><span>${label}</span></button>`).join('')}</div></section><div class="home-feed-layout"><section class="home-posts"><div class="home-composer"><span class="composer-avatar">${userAvatar()}</span><button class="composer-input" data-action="compose">Share a thought or ask a question…</button><button class="icon-button" data-action="compose" aria-label="Create a discussion">${svg('plus',17)}</button></div><div class="home-feed-label"><h2>For you</h2><span>Thoughtful conversations</span></div><div class="discussion-list">${state.posts.slice(0,4).map(postCard).join('')}</div><button class="btn full-width" data-route="community">See more conversations ${svg('arrow',13)}</button></section><aside class="home-aside"><a class="health-shortcut" href="#" data-route="my-health"><span class="shortcut-icon">${svg('heart',17)}</span><span><strong>Your health space</strong><small>Notes and care conversations, when you need them</small></span><span class="topic-arrow">›</span></a><div class="home-gentle-note"><span class="overline">A gentle reminder</span><p>Your experience is yours to define. This demo keeps entries on this device.</p></div><button class="action-link" data-route="research">A question worth exploring <span>→</span></button></aside></div></div>`;
}function doctorDashboard(){return `${pageHeading('Professional workspace','A place for shared reports, care resources and thoughtful discussions.',`<button class="btn" data-route="professional">Profile</button><button class="btn primary" data-route="verification">Start credential review</button>`)}<div class="dashboard-banner"><div class="banner-copy"><div class="overline">Doctor workspace preview</div><h2>Good care starts with listening.</h2><p>Explore the tools planned for professional participation. No patient report is available until a patient shares it with explicit consent.</p><button class="btn" data-route="research">Open research hub ${svg('arrow',13)}</button></div>${welcomeIcon}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><h2>Professional verification</h2><span class="status-tag preprint">No claim submitted</span></div><p class="entry-note">Identity, registration and qualifications are reviewed as separate claims. This demo has no live application or registry connection.</p><button class="btn small" data-route="verification">Review verification steps</button></section><section class="card"><div class="card-head"><h2>Patient-shared reports</h2></div>${emptyState('No reports shared','A patient must choose to share a report before it appears in this workspace.')}</section></div>`}
function researcherDashboard(){return `${pageHeading('Research workspace','Manage a public profile and connect with women’s health research.',`<button class="btn" data-route="professional">Profile</button><button class="btn primary" data-action="upload-research">Add publication</button>`)}<div class="dashboard-banner"><div class="banner-copy"><div class="overline">Researcher workspace preview</div><h2>Make your work easier to find.</h2><p>Prepare a verified profile, share publications and join evidence-focused conversations. Verification is not active in this demo.</p><button class="btn" data-route="research">Explore the research hub ${svg('arrow',13)}</button></div>${welcomeIcon}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><h2>Publication collection</h2><button class="action-link" data-route="research">Research hub →</button></div>${emptyState('No publications added','Add a source-backed publication to create your profile collection.',`<button class="btn small" data-action="upload-research">Add publication</button>`)}</section><section class="card"><div class="card-head"><h2>Profile verification</h2><span class="status-tag preprint">Not started</span></div><p class="entry-note">Academic identity and institutional affiliation are not verified in this prototype.</p><button class="btn small" data-route="verification">View verification steps</button></section></div>`}
function explorerDashboard(){return `${pageHeading('Welcome to Vericove','Explore women’s health research and community knowledge.',`<button class="btn" data-route="research">Explore research</button><button class="btn primary" data-route="community">Visit community</button>`)}<section class="research-hero"><div class="research-hero-copy"><div class="overline">Open knowledge, made easier to find</div><h2>Curiosity can lead to better questions.</h2><p>Browse research and community conversations. This demo has no connected data service. Avoid entering personal or health information.</p></div></section><div class="dashboard-grid"><section class="card"><div class="card-head"><h2>Research previews</h2><button class="action-link" data-route="research">Research hub →</button></div>${papers().slice(0,2).map(paperCard).join('')}</section><section class="card"><div class="card-head"><h2>Open community spaces</h2></div><div class="community-list">${communityItems()}</div></section></div>`}

function contextTabs(active,items){return `<nav class="context-tabs" aria-label="Section navigation">${items.map(([id,label])=>`<button class="${id===active?'active':''}" data-route="${id}">${label}</button>`).join('')}</nav>`}
const healthTabs=[['my-health','Journal'],['timeline','Timeline'],['records','Records'],['medications','Treatments'],['reports','Reports']];
const discoverTabs=[['discover','Overview'],['care','Care'],['research','Research'],['matches','Research matches']];
function discoverPage(){const preview=papers()[0]?paperCard(papers()[0]):emptyState('No research previews yet','Source-backed research will appear here when a literature source is connected.');return `${pageHeading('Discover','Browse care specialties, research previews and researcher matching.')}<section class="research-hero"><div class="research-hero-copy"><div class="overline">Thoughtful discovery</div><h2>Start with what you want to understand.</h2><p>Browse care providers, publications and researchers. Your private health information is not used to personalize these results.</p></div></section><div class="discover-grid"><button class="discover-card" data-route="care"><span class="discover-icon tone-rose">${svg('pin',19)}</span><small>CARE DIRECTORY</small><strong>Find a provider</strong><p>See specialties, locations and credential status. Patient experience is labeled separately.</p><span class="text-link">Explore care ${svg('arrow',12)}</span></button><button class="discover-card" data-route="research"><span class="discover-icon tone-sage">${svg('book',19)}</span><small>OPEN RESEARCH</small><strong>Read what’s being studied</strong><p>Browse research summaries with clear source and evidence-status labels.</p><span class="text-link">Explore research ${svg('arrow',12)}</span></button><button class="discover-card" data-route="matches"><span class="discover-icon tone-lav">${svg('spark',19)}</span><small>RESEARCH MATCHING</small><strong>Find relevant research teams</strong><p>Explore public expertise by topic. A match is not a clinical referral.</p><span class="text-link">View research teams ${svg('arrow',12)}</span></button></div><section class="card" style="margin-top:14px"><div class="card-head"><div><h2>Research feed preview</h2><p>Source-backed research will appear after a literature source is connected.</p></div><button class="action-link" data-route="research">Open research feed →</button></div>${preview}</section>`}
function profilePage(){const who=user(),role=who.role,handle=who.handle||'member',name=who.displayName||who.name||'Vericove member',coverStyle=who.bannerImage?`style="background-image:url('${esc(who.bannerImage)}')"`:'';const owns=state.posts.filter(post=>post.ownerHandle===handle);const follows=state.profileFollows||[];const followers=follows.filter(item=>item.to===handle).map(item=>item.from);const following=follows.filter(item=>item.from===handle).map(item=>item.to);const tab=state.profileTab||'Posts';const tabs=role==='doctor'?['Posts','About','Qualifications']:role==='researcher'?['Posts','Publications','Research interests','About']:['Posts','Replies','Media','About'];const tabContent=tab==='Posts'?owns.map(postCard).join('')||emptyState('Your story starts here','When you share a community post under your profile name, it will appear here.',`<button class="btn small" data-action="compose">Write a post</button>`):tab==='About'?`<section class="card profile-about"><h2>About ${esc(name)}</h2><p>${esc(who.bio||'A little about this member will appear here.')}</p>${role==='doctor'?`<div class="record-list"><div class="record"><span class="record-main"><strong class="record-title">Specialty</strong><small class="record-desc">${esc(who.specialty||'Not added')}</small></span><span class="status-tag preprint">Not verified</span></div></div>`:role==='researcher'?`<p class="entry-meta">${esc(who.institution||'Institution not added')}</p>`:''}<p class="profile-private-note">${svg('shield',13)} Private details and health records are not part of this profile.</p></section>`:tab==='Replies'?emptyState('No replies yet','Replies you make in community discussions will appear here.'):tab==='Media'?emptyState('No media yet','Photos shared with your posts will appear here.'):tab==='Qualifications'?`<section class="card"><div class="research-sidebar-box"><strong>Credential review required</strong>Credentials entered on a profile are self-reported until each claim is reviewed by an authorized reviewer.</div><button class="btn small" data-route="verification" style="margin-top:12px">View verification status</button></section>`:tab==='Publications'?(state.publications||[]).map(item=>`<article class="paper"><h3>${esc(item.title)}</h3><p>${esc(item.source)}</p><span class="status-tag preprint">${esc(item.status||'Unreviewed')}</span></article>`).join('')||emptyState('No publications yet','Add a source link to begin building your research profile.'):tab==='Research interests'?`<section class="card"><div class="interest-grid">${(who.interests||[]).map(item=>`<span class="interest-chip selected">${esc(item)}</span>`).join('')||'No research interests added yet.'}</div></section>`:'';return `${pageHeading('Your profile','A personal space for your story, interests and community.',`<button class="btn" data-action="edit-profile">${svg('settings')}Edit profile</button><button class="btn" data-route="settings">Privacy</button>`)}<section class="social-profile"><div class="social-profile-cover banner-${esc(who.banner||'warm')}" ${coverStyle}><label class="cover-edit">${svg('upload',13)} Edit cover<input id="profile-banner-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden></label></div><div class="social-profile-body"><div class="profile-heading-row"><div class="profile-avatar-wrap"><div class="profile-large">${userAvatar(who)}</div><button type="button" class="avatar-edit" title="Change profile picture" data-action="open-avatar-picker">${svg('upload',13)}</button></div><div class="profile-action-group"><button class="btn" data-action="profile-preview">${svg('eye',14)} Preview public profile</button><button class="btn" data-action="dm-coming">${svg('chat',14)} Message <span>Coming soon</span></button></div></div><div class="profile-title-row"><div><span class="role-kicker">${role==='patient'?'COMMUNITY MEMBER':role.toUpperCase()}${role==='doctor'||role==='researcher'?'<span class="status-tag preprint">Not verified</span>':''}</span><h2>${esc(name)}</h2><p class="username">@${esc(handle)}</p></div><button class="profile-more" data-action="profile-menu" aria-label="More profile options">${svg('more')}</button></div><p class="profile-bio">${esc(who.bio||'Tell the community a little about yourself…')}</p><div class="profile-facts">${role==='doctor'?`<span>${svg('heart',13)}${esc(who.specialty||'Specialty not added')}</span>`:role==='researcher'?`<span>${svg('book',13)}${esc(who.institution||'Researcher')}</span>`:''}${(who.interests||[]).slice(0,4).map(item=>`<span>${esc(item)}</span>`).join('')}</div><div class="profile-stat-row"><button data-action="profile-count" data-list="posts"><strong>${owns.length}</strong><span>Posts</span></button><button data-action="profile-count" data-list="followers"><strong>${followers.length}</strong><span>Followers</span></button><button data-action="profile-count" data-list="following"><strong>${following.length}</strong><span>Following</span></button></div><nav class="profile-tabs" role="tablist">${tabs.map(item=>`<button role="tab" aria-selected="${tab===item}" class="${tab===item?'active':''}" data-profile-tab="${item}">${item}</button>`).join('')}</nav><div class="profile-tab-content">${tabContent}</div></div></section><div class="auth-notice">Your account and profile are stored in this browser preview. Posts and follow relationships are not synced to a server.</div>`}

function journalPage(){const list=state.entries.map(entry=>`<article class="entry"><span class="entry-icon">${svg('pulse',15)}</span><div class="entry-main"><div class="entry-title">${esc(entry.symptom)}</div><div class="entry-meta">${fmtDate(entry.date)}${entry.time?` · ${esc(entry.time)}`:''} · ${esc(entry.duration||'Duration not recorded')}</div>${entry.note?`<div class="entry-note">${esc(entry.note)}</div>`:''}</div><div class="entry-side"><span class="severity ${entry.severity.toLowerCase()}">${esc(entry.severity)}</span></div></article>`).join('');return `${pageHeading('My health','Your health notes and care documents, at your pace.',`${addButton()}<button class="btn" data-route="reports">${svg('file')}Prepare summary</button>`)}<div class="split-layout"><div><div class="filter-row"><button class="pill active" data-filter="All">All entries</button><button class="pill" data-filter="Symptoms">Symptoms</button><button class="pill" data-filter="Medication">Medication</button><button class="pill" data-filter="Notes">Notes</button><span style="margin-left:auto;font-size:9px;color:#9b9ca2">${state.entries.length} sample entries</span></div><div class="entry-list">${list||emptyState('Your journal is ready when you are','Start with a symptom, question or observation. Small details are enough.',addButton())}</div></div><aside class="stack side-card"><section class="card"><div class="card-head"><h2>Today, at a glance</h2></div><div class="insight-box"><div class="insight-title">${svg('spark')}A gentle prompt</div><p>How has your energy felt today? You can log it now or come back when it suits you.</p><button class="btn small" data-action="log-symptom">Add a note</button></div></section><section class="card"><div class="card-head"><h2>Prototype storage</h2></div><div class="research-sidebar-box"><strong>${svg('shield',13)} Browser-only sample</strong>This demo uses local browser storage, which is not a secure health-record system. Don’t enter real health information.</div></section></aside></div>`}
function timelinePage(){return `${pageHeading('Health timeline','See your notes and health events in context.',`<button class="btn" data-route="my-health">${svg('heart')}Journal</button>${addButton()}`)}<div class="split-layout"><section class="card"><div class="card-head"><div><h2>Your health over time</h2><p>Sample chart · not based on your notes</p></div><div class="chart-legend"><span><i class="legend-dot" style="background:#9879a0"></i>Energy</span><span><i class="legend-dot" style="background:#d0a094"></i>Discomfort</span></div></div>${graph()}<div class="quiet-note">${svg('spark',12)}The timeline helps organize your notes; it does not determine causes.</div><div class="nav-separator"></div><div class="timeline">${state.entries.map(entry=>`<article class="timeline-event"><div class="timeline-date">${fmtDate(entry.date)}${entry.time?` · ${esc(entry.time)}`:''}</div><strong>${esc(entry.symptom)} <span class="severity ${entry.severity.toLowerCase()}">${esc(entry.severity)}</span></strong><p>${esc(entry.note||entry.duration||'No additional note recorded.')}</p></article>`).join('')}</div></section><aside class="stack side-card"><section class="card"><div class="card-head"><h2>What you’ve logged</h2></div><div class="bar-chart"><div class="bar-item"><span>Discomfort</span><div class="bar-track"><div class="bar-fill" style="width:78%"></div></div><b>6</b></div><div class="bar-item"><span>Energy</span><div class="bar-track"><div class="bar-fill" style="width:60%"></div></div><b>4</b></div><div class="bar-item"><span>Dizziness</span><div class="bar-track"><div class="bar-fill" style="width:30%"></div></div><b>2</b></div></div><p class="entry-note">Illustrative counts only · not linked to journal entries.</p></section></aside></div>`}
function recordsPage(){const cards=state.records.map((record,i)=>`<article class="record"><span class="record-icon">${svg(record.type==='Lab result'?'trend':'file',15)}</span><span class="record-main"><strong class="record-title">${esc(record.name)}</strong><small class="record-desc">${esc(record.type)} · ${fmtDate(record.date)}<br>${esc(record.file||'Added to your private records')}</small></span><button class="record-end" data-action="view-record" data-name="${esc(record.name)}" aria-label="View record">${svg('eye',15)}</button></article>`).join('');return `${pageHeading('Medical records','Keep reports, results and care notes together.',`<button class="btn" data-route="reports">${svg('file')}Consultation report</button><button class="btn primary" data-action="upload-record">${svg('upload')}Add a record</button>`)}<div class="doc-grid">${cards||emptyState('No records yet','Add a report or test result to keep everything together.')}</div><section class="card" style="margin-top:13px"><div class="card-head"><div><h2>Add a record</h2><p>Choose a document from your device. Files stay in this local demo only.</p></div></div><label class="dropzone"><strong>Drop a file here or choose a document</strong><small>PDF, PNG or JPG · Sample only · not a real record</small><span class="btn small">Choose file</span><input id="record-file" type="file" accept=".pdf,.png,.jpg,.jpeg" /></label><div class="quiet-note" style="border:0">${svg('shield',12)}In a deployed app, records should be encrypted and stored with restricted access.</div></section>`}
function medicationsPage(){const list=state.medications.map(item=>`<article class="record"><span class="record-icon">✚</span><span class="record-main"><strong class="record-title">${esc(item.name)}</strong><small class="record-desc">${esc(item.notes||'No experience note added')} · Added ${fmtDate(item.date)}</small></span><button class="record-end" data-action="remove-medication" data-id="${esc(item.id)}" aria-label="Remove treatment note">${svg('close',14)}</button></article>`).join('');return `${pageHeading('Treatments','Record treatments and notes from your own experience.',`<button class="btn primary" data-action="add-medication">${svg('plus')}Add a treatment</button>`)}<div class="split-layout"><section class="card"><div class="card-head"><div><h2>Your treatment notes</h2><p>Stored in this browser demo only</p></div></div>${list?`<div class="record-list">${list}</div>`:emptyState('No treatment notes yet','Add an item when you want to remember what you are taking or noticing.')}</section><aside class="card side-card"><div class="card-head"><h2>Experience notes</h2></div><div class="research-sidebar-box"><strong>For a care conversation</strong>Record changes you notice and bring questions to a qualified healthcare professional. This app does not recommend treatment changes.</div></aside></div>`}
function reportsPage(){return `${pageHeading('Consultation reports','Turn your notes into a clear summary for a care conversation.',`<button class="btn primary" data-action="generate-report">${svg('plus')}Prepare a summary</button>`)}<div class="split-layout"><section class="card"><div class="card-head"><div><h2>Your report preview</h2><p>Only the information you choose is included.</p></div><span class="status-tag">Private draft</span></div><h3 style="font:700 13px Manrope;margin:8px 0">Health summary</h3><p class="entry-note">Prepared ${fmtDate(isoToday)} · Reporting period: last 30 days</p><div class="nav-separator"></div><h3 style="font:700 10px Manrope">Topics you have recorded</h3><p class="entry-note">${[...new Set(state.entries.map(e=>e.symptom))].map(esc).join(' · ')||'No symptoms logged yet'}</p><h3 style="font:700 10px Manrope;margin-top:17px">Recent notes</h3>${state.entries.slice(0,3).map(e=>`<p class="entry-note"><b>${fmtDate(e.date)}:</b> ${esc(e.symptom)} — ${esc(e.severity)}. ${esc(e.note||'')}</p>`).join('')}<div class="nav-separator"></div><div class="form-check"><input type="checkbox" id="report-consent" /><label for="report-consent">I reviewed this summary and want to create a shareable copy.</label></div><button class="btn" data-action="share-report">${svg('send')}Create shareable copy</button></section><aside class="card side-card"><div class="card-head"><h2>Built for a better conversation</h2></div><div class="research-sidebar-box"><strong>You remain in control</strong>A report is only shared when you choose to share it. It organizes the information you entered; it cannot diagnose a condition.</div></aside></div>`}

function communityItems(){return `<div class="community-item"><span class="community-mark">✿</span><span><strong>Endometriosis support</strong><small>Condition-based space</small></span><button class="join" data-action="follow" data-community="Endometriosis support">${state.followed.includes('Endometriosis support')?'Joined':'Join'}</button></div><div class="community-item"><span class="community-mark">☼</span><span><strong>Living with chronic pain</strong><small>Shared experience space</small></span><button class="join" data-action="follow" data-community="Living with chronic pain">${state.followed.includes('Living with chronic pain')?'Joined':'Join'}</button></div><div class="community-item"><span class="community-mark">♡</span><span><strong>Women’s health questions</strong><small>Question and support space</small></span><button class="join" data-action="follow" data-community="Women’s health questions">${state.followed.includes('Women’s health questions')?'Joined':'Join'}</button></div>`}
function postCard(post){
  const vote=post.vote||(post.voted?1:0);
  const own=post.ownerHandle===user().handle;return `<article class="post-card" id="${esc(post.id)}"><div class="post-top">${userAvatar({name:post.author,avatarTone:'anon'})}<div><button class="post-author member-link" data-action="view-member" data-name="${esc(post.author)}">${esc(post.author)} <small>· ${post.anonymous===false?'Member':'Pseudonym'}</small></button><div class="post-community">in ${esc(post.community)} · ${esc(post.time)}</div></div><span class="post-tag">${esc(post.tag)}</span><button class="post-menu" data-action="${own?'own-post-menu':'report-post'}" data-id="${esc(post.id)}" aria-label="${own?'Post options':'Report discussion'}">···</button></div><h3 class="post-title">${esc(post.title)}</h3><p class="post-body">${esc(post.body)}</p>${sessionMedia.has(post.id)?(sessionMedia.get(post.id).type==='video'?`<video class="post-media" src="${sessionMedia.get(post.id).url}" controls playsinline preload="metadata" aria-label="Video attached to this post"></video>`:`<img class="post-media" src="${sessionMedia.get(post.id).url}" alt="Photo attached to this conversation" loading="lazy" />`):''}<div class="post-footer"><button class="post-action ${vote===1?'selected':''}" data-action="vote" data-vote="1" data-id="${esc(post.id)}" aria-label="Mark helpful">${svg('up',13)}Helpful · ${post.votes}</button><button class="post-action ${vote===-1?'selected':''}" data-action="vote" data-vote="-1" data-id="${esc(post.id)}" aria-label="Not helpful">${svg('down',13)}Not for me</button><button class="post-action" data-action="toggle-comments" data-id="${esc(post.id)}">${svg('comment',13)}${post.comments.length} replies</button><button class="post-action" data-action="share-post" data-id="${esc(post.id)}">${svg('send',12)}Share</button><button class="post-action save ${post.saved?'selected':''}" data-action="save-post" data-id="${esc(post.id)}">${svg('bookmark',13)}${post.saved?'Saved':'Save'}</button></div>${post.comments?.[0]?`<div class="comment-preview"><strong>${esc(post.comments[0].author)}:</strong> ${esc(post.comments[0].text)}</div>`:''}<div class="comments" data-comments="${esc(post.id)}" hidden>${post.comments.map(c=>`<div class="comment"><strong>${esc(c.author)}:</strong> ${esc(c.text)}</div>`).join('')}<form class="comment-form" data-comment="${esc(post.id)}"><input name="comment" placeholder="Add a thoughtful reply…" aria-label="Reply" required /><button type="submit">Reply</button></form></div></article>`
}
function renderPostsMarkup(view){let posts=[...state.posts];if(view==='Following')posts=posts.filter(post=>state.followed.includes(post.community));if(view==='Videos')posts=posts.filter(post=>sessionMedia.get(post.id)?.type==='video');if(view==='Posts')posts=posts.filter(post=>post.tag!=='Video');if(view==='Helpful')posts.sort((a,b)=>b.votes-a.votes);return posts.map(postCard).join('')||emptyState(view==='Videos'?'No videos yet':'Nothing here yet',view==='Videos'?'Share a short video to start your community video feed.':'Follow a circle or share the first conversation.')}
export function renderCommunityFeed(view){state.communityView=view;const list=$('#discussion-list');if(!list)return;list.classList.toggle('video-feed',view==='Videos');list.innerHTML=renderPostsMarkup(view);$$('[data-community-view]').forEach(tab=>{const active=tab.dataset.communityView===view;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active))});const label=$('.community-feed-label span:last-child');if(label)label.textContent=view==='Videos'?'Short videos · scroll to keep watching':'Thoughtful conversations · pseudonymous by default'}
function communityPage(){
  const stories=state.stories||[],view=state.communityView||'FYP';
  const storyRail=`<section class="social-stories" aria-label="Community stories"><div class="section-kicker"><h2>Stories</h2><button class="text-link" data-action="add-story">Your story +</button></div><div class="story-rail"><button class="story-item" data-action="add-story"><span class="story-orb add">${svg('plus',18)}</span><span>Add story</span></button>${stories.map(story=>`<button class="story-item" data-action="view-story" data-id="${esc(story.id)}"><span class="story-orb story-ring"><span>${esc(story.initials||'VC')}</span></span><span>${esc(story.author)}</span></button>`).join('')||[['SoftMorning','SM'],['KindOak','KO'],['MapleSky','MS']].map(([name,initials])=>`<button class="story-item" data-action="story-prompt" data-name="${name}"><span class="story-orb story-ring"><span>${initials}</span></span><span>${name}</span></button>`).join('')}</div></section>`;
  const tabs=['FYP','Posts','Following','Videos'];
  return `${pageHeading('Community','Stories, conversations and short videos from your circles.',`<button class="btn" data-action="guidelines">Guidelines</button>`)}<div class="community-layout"><section class="community-main">${storyRail}<div class="social-composer"><button class="composer-avatar" data-route="profile" aria-label="Your profile">${userAvatar()}</button><button class="composer-input" data-action="compose">Share a thought with your community…</button><button class="social-create" data-action="compose" aria-label="Create a post">${svg('plus',18)}</button><div class="social-create-actions"><button data-action="compose">${svg('file',15)} Post</button><button data-action="add-story">${svg('spark',15)} Story</button><button data-action="compose-video">${svg('upload',15)} Video</button></div></div><div class="community-tabs social-tabs" role="tablist" aria-label="Community feed"><span class="tab-caption">Explore</span>${tabs.map(tab=>`<button class="${view===tab?'active':''}" role="tab" aria-selected="${view===tab}" data-community-view="${tab}">${tab==='FYP'?'For you':tab}</button>`).join('')}</div><div class="community-feed-label"><span class="tiny-dot"></span><span>${view==='Videos'?'Short videos · scroll to keep watching':'Thoughtful conversations · pseudonymous by default'}</span></div><div class="discussion-list ${view==='Videos'?'video-feed':''}" id="discussion-list">${renderPostsMarkup(view)}</div></section><aside class="community-side"><section class="community-side-card"><div class="card-head"><div><h2>Your circles</h2><p>Find a space that feels right</p></div></div><div class="community-list">${communityItems()}</div><button class="text-link" data-action="browse-communities">Explore all circles →</button><p class="community-privacy-note">Community conversations are peer support, not medical advice. Protect identifying details.</p></section></aside></div><button class="community-fab" data-action="compose" aria-label="Start a discussion">${svg('plus',19)}<span>Write</span></button>`;
}
function papers(){return researchPapers}
function paperCard(paper){const saved=state.savedPapers.includes(paper.id);return `<article class="paper" data-paper="${esc(paper.id)}"><div class="paper-icon">${svg('book',14)}</div><div class="paper-main"><div class="paper-type">${esc(paper.type)} · ${esc(paper.topic)}</div><h3>${esc(paper.title)}</h3><div class="authors">${esc(paper.authors)}</div><p>${esc(paper.summary)}</p><div class="paper-foot"><span class="source-tag">${esc(paper.status)}</span><span class="source-tag neutral">${esc(paper.source)}</span><button class="action-link" data-action="paper-details" data-id="${esc(paper.id)}">Details →</button><button class="action-link" data-action="save-paper" data-id="${esc(paper.id)}">${saved?'Saved':'Save'}</button></div></div></article>`}
function researchPage(){return `${pageHeading('Women’s health research','Discover evidence and keep its context close.',`<button class="btn" data-route="matches">${svg('spark')}Find researchers</button><button class="btn" data-route="community">Discuss a question</button>`)}<section class="research-hero"><div class="research-hero-copy"><div class="overline">Open research hub</div><h2>Knowledge grows when it can be found.</h2><p>Explore publications, researcher profiles and studies. Evidence status, source links and limitations stay visible as you read.</p><form class="research-search" id="research-search"> <input name="q" placeholder="Search a condition, symptom or research topic" aria-label="Search research" /><button class="btn primary" type="submit">${svg('search',13)}Search</button></form></div></section><div class="research-tabs"><button class="pill active" data-research-tab="All research">All research</button><button class="pill" data-research-tab="Endometriosis">Endometriosis</button><button class="pill" data-research-tab="Pelvic pain">Pelvic pain</button><button class="pill" data-research-tab="Menstrual health">Menstrual health</button><button class="pill" data-research-tab="My saved">My saved</button></div><div class="split-layout"><section><div class="card-head"><div><h2>Research feed</h2><p>Sample items · literature source not connected</p></div><button class="action-link" disabled title="Relevance sorting will be available when a literature source is connected">${svg('sort',13)} Sort by relevance</button></div><div class="paper-list" id="paper-list">${papers().map(paperCard).join('')}</div></section><aside class="stack side-card"><section class="card"><div class="card-head"><div><h2>Researcher matches</h2><p>Related to topics you follow</p></div></div><div class="research-sidebar-box"><strong>No researcher data source connected</strong>Verified names, affiliations and publication matches will appear here when a public researcher registry is connected.</div><button class="btn small" data-route="matches">See matching researchers</button></section><section class="card"><div class="card-head"><h2>Read with context</h2></div><div class="research-sidebar-box"><strong>Evidence labels matter</strong>Peer-reviewed publications, preprints and clinical observations have different evidence status. A research finding is not personal medical advice.</div></section><section class="card"><div class="card-head"><h2>Research gaps</h2></div><div class="research-sidebar-box"><strong>Source connection needed</strong>Gap summaries should be generated from a traceable literature review with its limits shown.</div></section></aside></div>`}
function matchesPage(){const drafts=state.enquiries.map(item=>`<article class="record"><span class="record-icon">${svg('file')}</span><span class="record-main"><strong class="record-title">Research enquiry draft</strong><small class="record-desc">Saved ${fmtDate(item.date)} · Not addressed or sent</small></span></article>`).join('');return `${pageHeading('Research matches','Explore public research expertise connected to a topic.',`<button class="btn" data-action="share-consent">${svg('shield')}Sharing choices</button>`)}<div class="research-sidebar-box" style="margin-bottom:12px"><strong>Matches are exploratory</strong>Suggestions should be based on publications and public researcher records. They are not clinical referrals or diagnoses. No live researcher source is connected, and your journal is not shared.</div><section class="card"><div class="card-head"><div><h2>Researcher match preview</h2><p>Example of how a topic connection will be explained</p></div><span class="status-tag preprint">Preview</span></div><div class="record"><span class="record-icon">${svg('spark')}</span><span class="record-main"><strong class="record-title">Relevant researcher profile</strong><small class="record-desc">Name, affiliation, publications and contact details will appear here after a public researcher-data source is connected.</small></span><button class="btn small" disabled>Profile unavailable</button></div><div class="paper-type" style="margin-top:14px">Why this match</div><p class="entry-note">The system will show matched public research topics and publication links. No percentage score is displayed without validated matching data.</p><div class="modal-actions"><button class="btn" data-route="research">Explore research instead</button><button class="btn" data-action="share-consent">Review sharing choices</button></div></section>${drafts?`<section class="card" style="margin-top:12px"><div class="card-head"><h2>Your local enquiry drafts</h2></div><div class="record-list">${drafts}</div></section>`:''}`}
function carePage(){const examples=[['Provider listing preview 01','Obstetrics & gynecology'],['Provider listing preview 02','Reproductive health'],['Provider listing preview 03','Pelvic health']];return `${pageHeading('Find care','Explore provider specialties and patient-experience information.',`<button class="btn" data-route="settings">${svg('settings')}Care preferences</button>`)}<div class="care-toolbar"><label class="care-search">${svg('search',14)}<input id="doctor-search" placeholder="Search a specialty" aria-label="Search providers" /></label></div><div class="research-sidebar-box" style="margin-bottom:12px"><strong>Directory preview</strong>No live provider directory is connected. The entries below are interface examples only; no clinician, credential, location, availability or patient rating is represented.</div><div class="filter-row"><button class="pill active" data-care-filter="All providers">All specialties</button><button class="pill" data-care-filter="Gynecology">Gynecology</button><button class="pill" data-care-filter="Reproductive">Reproductive health</button><button class="pill" data-care-filter="Pelvic">Pelvic health</button></div><div class="split-layout"><section class="doctor-list" id="doctor-list">${examples.map(([name,specialty],i)=>`<article class="doctor-card" data-doctor="${esc(specialty.toLowerCase())}"><span class="avatar ${['alt','blush','dark'][i]}">${svg('user',18)}</span><div class="doctor-main"><h3>${name}</h3><p>${specialty}</p><p>Location and consultation details unavailable</p><span class="status-tag preprint">Illustrative profile · Not verified</span></div><button class="btn small" data-action="doctor-profile" data-name="${name}">Profile preview</button></article>`).join('')}</section><aside class="stack side-card"><section class="card"><div class="card-head"><h2>Compare with care</h2></div><div class="research-sidebar-box"><strong>Experience feedback will be structured</strong>Future profiles can summarize listening, respect and shared decision-making. Patient reviews remain individual experiences and are not clinical-quality ratings.</div></section><section class="card"><div class="card-head"><h2>Privacy-aware reviews</h2></div><p class="entry-note">The review form is a local interaction preview. It does not identify a real provider or publish feedback.</p><button class="btn small" data-action="write-review">Preview review form</button></section></aside></div>`}

function professionalPage(){
  const role=user().role;
  if(role==='patient'||role==='explorer') return `${pageHeading('Professional workspaces','Professional verification tools are available to clinician and researcher accounts.',`<button class="btn primary" data-action="change-role">Preview another workspace</button>`)}<section class="card">${emptyState('Professional workspace preview','Switch to a doctor or researcher demo role to view this area.')}</section>`;
  const publications=state.publications.map(item=>`<article class="record"><span class="record-icon">${svg('book')}</span><span class="record-main"><strong class="record-title">${esc(item.title)}</strong><small class="record-desc">${esc(item.source)} · ${esc(item.status)} (self-reported)</small></span></article>`).join('');
  return `${pageHeading('Professional profile','Manage the profile information you choose to make public.')}<section class="card"><div class="card-head"><h2>Professional profile</h2><span class="status-tag preprint">Not verified</span></div><div class="research-sidebar-box"><strong>Profile preview</strong>Identity, registration, education and achievements are separate claims. No credentials are checked by this prototype.</div><div class="record-list" style="margin-top:12px"><div class="record"><span class="record-icon">${svg('user')}</span><span class="record-main"><strong class="record-title">Public profile</strong><small class="record-desc">Name, speciality, institution, interests and publications.</small></span><button class="btn small" data-route="verification">Verification steps</button></div><div class="record"><span class="record-icon">${svg('book')}</span><span class="record-main"><strong class="record-title">Publications and achievements</strong><small class="record-desc">Profile entries are self-reported until source checks exist.</small></span><button class="btn small" data-action="upload-research">Add</button></div>${publications}</div></section>`;
}
function verificationPage(){return `${pageHeading('Credential verification','Identity and each professional claim are checked separately.',`<button class="btn" data-route="professional">Back to profile</button>`)}<div class="split-layout"><section class="card"><div class="card-head"><div><h2>${user().role==='doctor'?'Doctor verification application':'Researcher verification'}</h2><p>Prototype only: do not enter real credentials. No upload or verification service is connected.</p></div><span class="status-tag preprint">Draft</span></div><div class="step-dots"><i class="active"></i><i></i><i></i><i></i><i></i></div><form id="verification-form"><div class="form-field"><label for="profession-type">Professional category</label><select name="profession" id="profession-type"><option>Allopathic doctor</option><option>AYUSH professional</option><option>Dentist</option><option>Nurse</option><option>Researcher</option><option>Other regulated professional</option></select><small class="form-hint">Different professional categories use different regulatory bodies.</small></div><div class="form-field"><label for="registration-number">Registration or professional identifier</label><input id="registration-number" name="registration" placeholder="Council / registry and registration number" required /></div><div class="form-field"><label for="qualification">Example qualification or academic affiliation</label><input id="qualification" name="qualification" placeholder="e.g. MBBS · issuing institution" required /></div><div class="form-field"><label for="credential-file">Example supporting document</label><input id="credential-file" name="evidence" type="file" accept=".pdf,.jpg,.jpeg,.png" /><small class="form-hint">Selecting a file only previews the control. It is not uploaded or saved.</small></div><div class="form-check"><input type="checkbox" required id="verify-attest" /><label for="verify-attest">I confirm that these details are accurate and agree to verification by an authorized reviewer.</label></div><button class="btn primary" type="submit">Preview verification steps</button></form></section><aside class="stack side-card"><section class="card"><div class="card-head"><h2>Verification stages</h2></div><div class="timeline"><div class="timeline-event"><strong>Identity</strong><p>Confirm the applicant matches the submitted identity evidence.</p></div><div class="timeline-event"><strong>Registration</strong><p>Check the relevant official professional registry.</p></div><div class="timeline-event"><strong>Qualifications</strong><p>Review each degree or claim independently.</p></div><div class="timeline-event"><strong>Reviewer decision</strong><p>Approved, needs evidence, or not verified.</p></div></div></section><section class="card"><div class="research-sidebar-box"><strong>No badge on submission</strong>A professional badge is shown only after the applicable checks are complete.</div></section></aside></div>`}
function adminPage(){return `${pageHeading('Admin overview','Professional claims, community reports and platform operations.',`<button class="btn" data-route="moderation">${svg('shield')}Moderation queue</button>`)}<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Doctor verification</h2><p>Review identity, registration and each qualification as separate claims.</p></div></div>${emptyState('No connected applications','A secure professional-verification backend and authorized reviewer account are required before applications appear.')}</section><section class="card"><div class="card-head"><div><h2>Researcher verification</h2><p>ORCID, institutional affiliations and publication records.</p></div></div>${emptyState('No connected researcher profiles','Verification data sources and reviewer permissions are not configured.')}</section></div><section class="card" style="margin-top:12px"><div class="card-head"><div><h2>Data boundaries</h2><p>Operational requirements from the architecture</p></div></div><div class="research-sidebar-box"><strong>Separate identity, health, community and credential data</strong>A production service needs role-based access, audit logs, encrypted file storage and human review. This prototype has no administrator credentials or live queue.</div></section>`}
function moderationPage(){const reports=state.reports.map(report=>{const post=state.posts.find(item=>item.id===report.id);return `<article class="record"><span class="record-icon">${svg('chat')}</span><span class="record-main"><strong class="record-title">${esc(post?.title||'Post no longer available')}</strong><small class="record-desc">${esc(post?.community||'Community')} · ${esc(report.reason)}</small></span><button class="btn small" data-action="moderate" data-id="${esc(report.id)}">Review</button></article>`}).join('');return `${pageHeading('Community moderation','Review local example reports against the community guidelines.',`<button class="btn" data-route="admin">Admin overview</button>`)}<section class="card"><div class="card-head"><div><h2>Reported discussions</h2><p>Reports exist only in this browser preview.</p></div></div>${reports?`<div class="entry-list">${reports}</div>`:emptyState('No reports in this browser','Reports are not transmitted to a real moderation team.')}</section>`}
function notificationsPage(){return `${pageHeading('Notifications','Updates from the communities and topics you follow.',`<button class="btn" data-action="mark-read">Mark all as read</button>`)}<section class="card"><div class="activity-list">${state.notifications.map((n,i)=>`<div class="activity-row"><span class="activity-icon">${svg(i?'book':'chat',14)}</span><div class="activity-copy">${esc(n.title)}<small>${esc(n.time)}</small></div>${n.read?'<span class="entry-meta">Read</span>':'<span class="tiny-dot"></span>'}</div>`).join('')}</div></section>`}
function settingsPage(){
  const privacy=user().privacy||{};
  const notificationSettings={messages:true,community:true,productUpdates:false,...(state.notificationSettings||{})};
  const privacyFields=[['display','Display name'],['avatar','Profile picture'],['bio','Bio'],['interests','Interests'],['age','Age information'],['gender','Gender']];
  const notificationFields=[['messages','Messages and requests','A new message or conversation request'],['community','Community activity','Replies, reactions and followed communities'],['productUpdates','Product updates','Occasional notes about new Vericove features']];
  const toggle=(key,label,description,checked,attribute)=>`<label class="settings-toggle-row"><span><strong>${label}</strong><small>${description}</small></span><input class="settings-switch" type="checkbox" ${attribute}="${key}" ${checked?'checked':''} aria-label="${label}"></label>`;
  return `${pageHeading('Settings','Manage your privacy, notifications and account preferences.')}
    <div class="settings-layout">
      <div class="settings-main-column">
        <section class="card profile-privacy-settings settings-card">
          <div class="card-head"><div><h2>Profile visibility</h2><p>Choose what people can see on your public profile.</p></div><span class="status-tag">Private by default</span></div>
          ${privacyFields.map(([key,label])=>`<label class="privacy-row"><span><strong>${label}</strong><small>${['age','gender'].includes(key)?'Optional details stay private unless you choose otherwise.':'Choose who can see this on your profile.'}</small></span><select data-profile-privacy="${key}" aria-label="${label} visibility">${['Private','Followers only','Public'].map(value=>`<option ${privacy[key]===value?'selected':''}>${value}</option>`).join('')}</select></label>`).join('')}
          <p class="privacy-footnote">Email, exact date of birth and health records are never shown here. Health information has separate access controls.</p>
        </section>
        <section class="card settings-card">
          <div class="card-head"><div><h2>Notification preferences</h2><p>Choose which updates appear in this browser preview.</p></div></div>
          ${notificationFields.map(([key,label,description])=>toggle(key,label,description,notificationSettings[key],'data-notification-setting')).join('')}
          <p class="privacy-footnote">These preferences are saved on this device. Push and email delivery are not connected in this preview.</p>
        </section>
      </div>
      <aside class="settings-side-column">
        <section class="card settings-card">
          <div class="card-head"><div><h2>Experience</h2><p>Fine-tune your Vericove workspace.</p></div></div>
          ${toggle('darkMode','Dark appearance','Use a darker palette throughout Vericove.',state.uiTheme==='dark','data-theme-toggle')}
          ${toggle('uiSounds','Interface sounds','Soft feedback for clicks and section changes.',state.uiSounds!==false,'data-ui-sounds')}
        </section>
        <section class="card settings-card">
          <div class="card-head"><div><h2>Your choices</h2><p>Sharing stays under your control.</p></div></div>
          <div class="record-list">
            <div class="record"><span class="record-icon">${svg('shield')}</span><span class="record-main"><strong class="record-title">Research matching</strong><small class="record-desc">Selected health details stay off unless you choose to share them.</small></span><span class="status-tag">${state.consent.researchMatching?'On':'Off'}</span></div>
            <div class="record"><span class="record-icon">${svg('chat')}</span><span class="record-main"><strong class="record-title">Community identity</strong><small class="record-desc">Use your pseudonym separately from your public profile identity.</small></span><span class="status-tag">${user().anonymous===false?'Off':'On'}</span></div>
          </div>
        </section>
        <section class="card settings-card settings-account-card"><div><h2>Account</h2><p>End your current browser session.</p></div><button class="btn settings-signout-button" data-action="signout">${svg('arrow',15)} Sign out</button></section>
        <p class="settings-storage-note">Local preview · preferences stay in this browser.</p>
      </aside>
    </div>`;
}
function emptyState(title,body,action=''){return `<div class="empty-state"><strong>${esc(title)}</strong><p>${esc(body)}</p>${action}</div>`}
function renderWorkspace(){
  if(state.route==='community'){
    app.innerHTML=communityApplicationPage();
    const section=state.communitySection||'home';
    document.dispatchEvent(new CustomEvent('community:rendered',{detail:{section}}));
    if(renderWorkspace.lastRoute!==state.route||renderWorkspace.lastCommunitySection!==section){enterPage(app.querySelector('#vc-main-content'));}
    renderWorkspace.lastCommunitySection=section;
    renderWorkspace.lastRoute=state.route;
    renderWorkspace.reelObserver?.disconnect();
    const reelFeed=app.querySelector('.vc-reel-feed');
    if(reelFeed){reelFeed.querySelectorAll('[data-reel-video]').forEach(video=>{const card=video.closest('[data-reel-card]'),post=state.posts.find(item=>item.id===card?.dataset.reelId);if(post?.mediaPoster)video.poster=post.mediaPoster;const applyVideoRatio=()=>{if(video.videoWidth&&video.videoHeight)card?.style.setProperty('--reel-ratio',String(video.videoWidth/video.videoHeight));};if(video.readyState>=1)applyVideoRatio();video.addEventListener('loadedmetadata',applyVideoRatio,{once:true});});}
    if(reelFeed&&'IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){renderWorkspace.reelObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{const video=entry.target.querySelector('video');if(!video)return;video.loop=true;if(entry.isIntersecting&&entry.intersectionRatio>.55){video.play().catch(()=>{});}else video.pause();}),{root:reelFeed,threshold:[0,.55,.8]});reelFeed.querySelectorAll('[data-reel-card]').forEach(card=>renderWorkspace.reelObserver.observe(card));}
    return;
  }
  const previousRoute=renderWorkspace.lastRoute;
  const modalActive=state.route==='talk-to-mira';
  if(modalActive&&!renderWorkspace.backgroundRoute)renderWorkspace.backgroundRoute=previousRoute&&previousRoute!=='talk-to-mira'?previousRoute:'my-health';
  const displayRoute=modalActive?(renderWorkspace.backgroundRoute||'my-health'):state.route;
  if(!modalActive)renderWorkspace.backgroundRoute='';
  const routes={'dashboard':dashboard,'my-health':()=>healthPage('my-health'),'health-journal':()=>healthPage('health-journal'),'health-insights':()=>healthPage('health-insights'),'health-records':()=>healthPage('health-records'),'health-conversation':()=>healthPage('health-conversation'),'talk-to-mira':()=>healthPage('talk-to-mira'),'timeline':()=>healthPage('health-insights'),'records':()=>healthPage('health-records'),'medications':medicationsPage,'reports':reportsPage,'community':communityPage,'discover':discoverPage,'research':researchPage,'matches':matchesPage,'care':carePage,'profile':profilePage,'professional':professionalPage,'verification':verificationPage,'admin':adminPage,'moderation':moderationPage,'notifications':notificationsPage,'settings':settingsPage};
  const pageContent=(routes[displayRoute]||dashboard)();
  if(modalActive)app.removeAttribute('aria-live');else app.setAttribute('aria-live','polite');
  const role=user().role;
  const normalizedRoute=['health-journal','health-insights','health-records','health-conversation','talk-to-mira','timeline','records','medications','reports'].includes(displayRoute)?'my-health':role==='doctor'&&displayRoute==='professional'?'professional':role==='researcher'&&['research','matches'].includes(displayRoute)?displayRoute:['care','research','matches'].includes(displayRoute)?'discover':['professional','verification','notifications'].includes(displayRoute)?'profile':displayRoute;
  const mobileItems=role==='doctor'?[['dashboard','Appointments','calendar'],['community','Community','chat'],['professional','Practice','user']]:role==='researcher'?[['dashboard','Home','grid'],['research','Research','book'],['community','Community','chat'],['matches','Collaborate','spark']]:[['dashboard','Home','grid'],['my-health','My health','heart'],['community','Community','chat'],['discover','Discover','spark']];
  const moreItems=role==='doctor'?[['profile','Profile'],['verification','Credential review'],['notifications','Notifications'],['settings','Settings']]:role==='researcher'?[['profile','Profile'],['verification','Credential review'],['notifications','Notifications'],['settings','Settings']]:[['profile','Profile'],['health-journal','Journal'],['health-insights','Insights'],['health-records','Records'],['notifications','Notifications'],['settings','Settings']];
  const moreActive=moreItems.some(([id])=>id===displayRoute);
  app.innerHTML=`<div class="app-shell" ${modalActive?'inert aria-hidden="true"':''}>${workspaceSidebar()}<main class="main-column">${topbar(displayRoute)}<div class="page">${pageContent}</div></main></div><nav class="mobile-nav" aria-label="Primary navigation" ${modalActive?'inert aria-hidden="true"':''}>${mobileItems.map(([id,name,icon])=>`<button class="${id===normalizedRoute?'active':''}" data-route="${id}" aria-current="${id===normalizedRoute?'page':'false'}"><span class="nav-icon">${svg(icon,18)}</span><span>${name}</span></button>`).join('')}<details class="mobile-more ${moreActive?'has-active':''}"><summary aria-label="More sections" title="More sections"><span class="nav-icon">${svg('more',18)}</span><span>More</span></summary><div class="mobile-more-menu" role="menu" aria-label="More sections">${moreItems.map(([id,label])=>`<button type="button" role="menuitem" data-route="${id}" ${id===displayRoute?'aria-current="page"':''}>${label}</button>`).join('')}<button type="button" role="menuitem" data-action="signout">Log out</button></div></details></nav>${modalActive?healthPage('talk-to-mira',renderWorkspace.backgroundRoute):''}`;
  if(previousRoute!==state.route){enterPage(app.querySelector('.page'));animateSelection(app.querySelector('.nav-item.active, .mobile-nav button.active'));}
  renderWorkspace.lastCommunitySection='';
  renderWorkspace.lastRoute=state.route;
}

