export const auth = { mode:state.session?.loggedIn?'login':'landing', step:1, draft:{role:'patient',privacy:{display:'Followers only',avatar:'Followers only',bio:'Private',interests:'Followers only',age:'Private',gender:'Private'},interests:[],banner:'warm'} };
export const setAuthMode = mode => { auth.mode = mode; };
export const avatarAssets=Object.entries(import.meta.glob('/assets/PFPs/*.{jpg,jpeg,png,webp}',{eager:true,query:'?url',import:'default'})).map(([path,url])=>({path,url}));
auth.draft.avatar=avatarAssets.find(asset=>asset.path.endsWith('/Jaime.jpg'))?.url||avatarAssets[0]?.url||'';
const topics=['General wellness','Reproductive health','Menstrual health','PCOS & hormones','Pregnancy & motherhood','Mental wellbeing','Nutrition','Preventive care','Women’s health research'];
const stepNames=['Your account','Your identity','Your interests','Your privacy','A first look'];
function authPage(){const isSignup=auth.mode==='signup';const role=auth.draft.role||'patient',step=auth.step;const title=isSignup?(step===1?'A space that starts with you':step===2?'How would you like to be part of Vericove?':step===3?'Make it feel like yours':step===4?'Choose what others can see':'Your profile, at a glance'):(auth.mode==='forgot'?'Reset your password':'Welcome back');const intro=isSignup?(step===1?'Create your account to begin. You can shape the rest as you go.':step===2?'Choose the experience that fits you. You can update your profile later.':step===3?'A name, a portrait and a few words make this space yours.':step===4?'Your profile details are yours to share. Private is the starting point.':'Take a moment to review your profile before entering Vericove.'):(auth.mode==='forgot'?'Password reset needs a connected account service.':'Sign in to return to your health space.');let form='';
  if(isSignup&&step===1)form=`<form id="auth-form"><div class="form-field"><label for="full-name">Full name</label><input id="full-name" name="name" autocomplete="name" placeholder="Your name" required value="${esc(auth.draft.name||'')}" /></div><div class="form-field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required value="${esc(auth.draft.email||'')}" /></div><div class="form-field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="new-password" minlength="8" placeholder="At least 8 characters" required /></div><div class="form-grid signup-personal-grid"><div class="form-field"><label for="age-group">Age range</label><select id="age-group" name="ageGroup" required><option value="">Choose an age range</option><option value="under-18" ${auth.draft.ageGroup==="under-18"?"selected":""}>Under 18</option><option value="18-24" ${auth.draft.ageGroup==="18-24"?"selected":""}>18–24</option><option value="25-34" ${auth.draft.ageGroup==="25-34"?"selected":""}>25–34</option><option value="35-44" ${auth.draft.ageGroup==="35-44"?"selected":""}>35–44</option><option value="45-54" ${auth.draft.ageGroup==="45-54"?"selected":""}>45–54</option><option value="55-plus" ${auth.draft.ageGroup==="55-plus"?"selected":""}>55+</option><option value="prefer-not-to-say" ${auth.draft.ageGroup==="prefer-not-to-say"?"selected":""}>Prefer not to say</option></select><small class="form-hint">Age is private by default. Do not enter an exact birth date.</small></div><div class="form-field"><label for="gender-identity">Gender <span class="optional">Optional</span></label><input id="gender-identity" name="gender" value="${esc(auth.draft.gender||"")}" autocomplete="off" placeholder="How do you describe yourself?…" /></div><div class="form-field"><label for="location">Location <span class="optional">Optional</span></label><input id="location" name="location" value="${esc(auth.draft.location||"")}" autocomplete="off" placeholder="City or region…" /></div></div><div class="form-check"><input type="checkbox" required id="terms-check" /><label for="terms-check">I understand this is a local prototype and won’t enter real credentials or health details.</label></div><button class="btn primary auth-submit" type="submit">Continue ${svg('arrow',13)}</button></form>`;
  else if(isSignup&&step===2)form=`<div class="account-types">${[['patient','Individual','A private health space, community and topics that matter to you','♡'],['doctor','Doctor','A professional profile with a separate credential review','✳'],['researcher','Researcher','An academic profile for sharing work and finding collaborators','⌘']].map(([key,label,desc,icon])=>`<button type="button" class="account-type ${role===key?'selected':''}" data-role="${key}"><span class="type-icon">${icon}</span><span><strong>${label}</strong><small>${desc}</small></span><i>${role===key?'✓':''}</i></button>`).join('')}</div>`;
  else if(isSignup&&step===3){const pro=role==='doctor'||role==='researcher',coverStyle=auth.draft.bannerImage?`style="background-image:url('${esc(auth.draft.bannerImage)}')"`:'';form=`<div class="identity-layout"><div><label class="form-label">Profile picture</label><button type="button" class="avatar-launch" data-action="open-avatar-picker"><span class="avatar avatar-launch-preview">${auth.draft.avatar?`<img src="${esc(auth.draft.avatar)}" alt="" style="object-position:${Number(auth.draft.avatarCrop?.x??50)}% ${Number(auth.draft.avatarCrop?.y??50)}%;transform:scale(${Number(auth.draft.avatarCrop?.zoom??1)})"/>`:esc((auth.draft.displayName||auth.draft.name||'A').slice(0,1).toUpperCase())}</span><span><strong>Make it yours</strong><small>Choose an image or upload your own</small></span><span class="topic-arrow">›</span></button><small class="form-hint">Your picture can be changed any time.</small></div><div class="identity-fields"><div class="form-field"><label for="display-name">${pro?'Professional display name':'Display name'}</label><input id="display-name" name="displayName" value="${esc(auth.draft.displayName||auth.draft.name||'')}" maxlength="50" /></div><div class="form-field"><label for="username">Username</label><div class="username-input"><span>@</span><input id="username" name="handle" value="${esc(auth.draft.handle||'')}" maxlength="24" /></div></div><div class="form-field"><label for="profile-bio">${pro?'Professional bio':'Bio'} <span class="optional">Optional</span></label><textarea id="profile-bio" name="bio" maxlength="240" placeholder="${pro?'A little about your work and what you care about…':'Tell the community a little about yourself…'}">${esc(auth.draft.bio||'')}</textarea><small class="form-hint"><span id="bio-count">${(auth.draft.bio||'').length}</span> / 240 · Keep sensitive health details private.</small></div>${role==='doctor'?`<div class="form-field"><label>Professional details</label><input name="specialty" placeholder="Specialty (optional)" value="${esc(auth.draft.specialty||'')}"/><small class="form-hint">Credentials can be reviewed later. Submission does not verify a profile.</small></div>`:role==='researcher'?`<div class="form-field"><label>Academic details</label><input name="institution" placeholder="Institution or research field (optional)" value="${esc(auth.draft.institution||'')}"/><small class="form-hint">An ORCID or affiliation alone does not verify credentials.</small></div>`:''}</div><div class="banner-editor"><label class="form-label">Profile cover</label><div class="banner-presets">${[['warm','Soft morning'],['orchid','Orchid'],['garden','Garden']].map(([key,label])=>`<button class="banner-preset banner-${key} ${auth.draft.banner===key?'selected':''}" data-banner="${key}" aria-label="${label}"></button>`).join('')}<label class="upload-choice banner-upload">${svg('upload',13)} Upload cover <input type="file" id="banner-upload" accept="image/png,image/jpeg,image/webp" hidden></label></div></div><div class="profile-mini-preview"><div class="mini-banner ${auth.draft.banner?`banner-${auth.draft.banner}`:'banner-warm'}" ${coverStyle}></div><img src="${esc(auth.draft.avatar||avatarAssets[0]?.url||'')}" alt="" style="object-position:${Number(auth.draft.avatarCrop?.x??50)}% ${Number(auth.draft.avatarCrop?.y??50)}%;transform:scale(${Number(auth.draft.avatarCrop?.zoom??1)})"/><strong>${esc(auth.draft.displayName||auth.draft.name||'Your name')}</strong><small>@${esc(auth.draft.handle||'yourname')}</small><p>${esc(auth.draft.bio||'Your bio will appear here.')}</p></div></div>`;}
  else if(isSignup&&step===4)form=`<div class="interest-grid">${topics.map(topic=>`<button class="interest-chip ${(auth.draft.interests||[]).includes(topic)?'selected':''}" data-interest="${esc(topic)}">${esc(topic)}</button>`).join('')}</div><p class="form-hint">Interests help shape what you explore. They do not imply a health condition.</p><div class="privacy-list"><h3>Profile visibility</h3>${[['display','Display name'],['avatar','Profile picture'],['bio','Bio'],['interests','Interests'],['age','Age information'],['gender','Gender']].map(([key,label])=>`<label class="privacy-row"><span><strong>${label}</strong><small>${key==='age'||key==='gender'?'Private by default. You can add this later.':'Choose who can see this on your profile.'}</small></span><select data-privacy="${key}">${['Private','Followers only','Public'].map(value=>`<option ${((auth.draft.privacy||{})[key]||(['age','gender'].includes(key)?'Private':'Private'))===value?'selected':''}>${value}</option>`).join('')}</select></label>`).join('')}</div><label class="privacy-toggle"><input type="checkbox" id="anonymous-posting" ${auth.draft.anonymous?'checked':''}><span><strong>Use my pseudonym in community discussions</strong><small>Your profile visibility and health information sharing are separate.</small></span></label><p class="privacy-footnote">Your email and exact date of birth are never shown on your public profile. Health records have separate access controls.</p>`;
  else if(isSignup&&step===5){const d=auth.draft,coverStyle=d.bannerImage?`style="background-image:url('${esc(d.bannerImage)}')"`:'';form=`<div class="final-profile"><div class="final-banner banner-${esc(d.banner||'warm')}" ${coverStyle}></div><img class="final-avatar" src="${esc(d.avatar||avatarAssets[0]?.url||'')}" alt="Profile picture" style="object-position:${Number(d.avatarCrop?.x??50)}% ${Number(d.avatarCrop?.y??50)}%;transform:scale(${Number(d.avatarCrop?.zoom??1)})"/><div class="final-copy"><span class="role-kicker">${role==='patient'?'COMMUNITY MEMBER':role.toUpperCase()} PROFILE</span><h3>${esc(d.displayName||d.name||'Your name')}</h3><p class="username">@${esc(d.handle||'yourname')}</p><p>${esc(d.bio||'Your story can start whenever you’re ready.')}</p><div class="final-interests">${(d.interests||[]).map(t=>`<span>${esc(t)}</span>`).join('')||'<span>Interests can be added later</span>'}</div><div class="final-stats"><span><strong>0</strong> posts</span><span><strong>0</strong> followers</span><span><strong>0</strong> following</span></div></div><div class="preview-privacy">${svg('eye',14)} Profile preview · email and health records stay private</div></div>${role==='doctor'||role==='researcher'?`<div class="verification-note"><strong>Verification ${role==='doctor'?'is':'can be'} a separate step</strong><p>Submitting information will not create a verified badge. Authorized review is required, and this prototype has no secure submission service.</p></div>`:''}<label class="demo-consent"><input type="checkbox" id="privacy-check" checked><span>This is a local preview. My profile will be saved in this browser only.</span></label>`;}
  else if(auth.mode==='forgot')form=`<form id="auth-form"><div class="form-field"><label for="email">Email</label><input id="email" name="email" type="email" placeholder="you@example.com" required /></div><button class="btn primary auth-submit" type="submit">Request reset link</button><button class="btn ghost auth-submit" type="button" data-view="login">Back to sign in</button></form>`;
  else form=`<form id="auth-form"><div class="form-field"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required /></div><div class="form-field"><label for="workspace-role">Open workspace as</label><select id="workspace-role" name="role"><option value="patient">Individual</option><option value="doctor">Doctor</option><option value="researcher">Researcher</option><option value="explorer">Public explorer</option></select></div><div class="form-field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" placeholder="Your password" required /></div><div class="auth-inline-link"><button type="button" class="text-link" data-view="forgot">Forgot password?</button></div><button class="btn primary auth-submit" type="submit">Sign in ${svg('arrow',13)}</button><div class="auth-divider">or</div><button type="button" class="demo-button" data-action="demo-signin">Explore a demo workspace</button></form>`;
  const progress=isSignup?`<div class="onboard-progress"><div class="progress-track"><i style="width:${step*20}%"></i></div><div class="progress-label"><span>STEP ${step} OF 5</span><span>${stepNames[step-1]}</span></div></div>`:'';const footer=isSignup?`<div class="onboard-actions">${step>1?'<button class="btn ghost" data-action="onboard-back">Back</button>':'<span></span>'}${step<5?`<button class="btn primary" data-action="onboard-next">${step===2?'Continue as '+(role==='patient'?'Individual':role[0].toUpperCase()+role.slice(1)):'Continue'} ${svg('arrow',13)}</button>`:`<button class="btn primary" data-action="complete-signup">Create my Vericove profile ${svg('arrow',13)}</button>`}</div>`:'';
  app.innerHTML=`<main class="auth-shell ${isSignup?'onboarding-shell':''}"><section class="auth-art"><a class="brand" href="#" data-view="landing"><span class="brand-mark">${svg('heart',19)}</span><span class="brand-word">Vericove<small>UNDERSTAND · CARE · THRIVE</small></span></a><div class="auth-art-copy"><div class="overline">A quieter kind of health space</div><h1>Come as you are.<br>Make it your own.</h1><p>A place to understand your health, meet thoughtful people and follow the questions that matter to you.</p><div class="auth-art-orbit"><span>Care</span><i>✳</i><span>Community</span><i>♡</i><span>Research</span></div><div class="auth-quote">“Your experience deserves room to unfold.”<small>A reminder from Vericove</small></div></div><div class="auth-art-footer">A thoughtful space for health, community and research.</div></section><section class="auth-panel"><div class="auth-box"><div class="auth-topline">${isSignup?'Already have an account?':'New to Vericove?'} <button data-view="${isSignup?'login':'signup'}">${isSignup?'Sign in':'Create account'}</button></div>${progress}<h2>${title}</h2><p class="auth-intro">${intro}</p>${form}${footer}${!isSignup?`<div class="auth-notice">Prototype mode: sign-in is not checked by a server. Your demo workspace is remembered on this device. Do not enter real credentials or health information.</div>`:''}</div></section></main>`;}

export function render(){if(state.route!=='community'||auth.mode==='landing')document.dispatchEvent(new Event('community:exit'));if(auth.mode==='landing'){document.title='Vericove — A thoughtful space for women’s health';landing();return;}document.title=`${routeTitles[state.route]||'Vericove'} — Vericove`;if(!state.session?.loggedIn){authPage();return;}const previousRoute=renderWorkspace.lastRoute;renderWorkspace();document.dispatchEvent(new CustomEvent('mira:page-rendered',{detail:{route:state.route,previousRoute}}));}
export function go(route){if(route!=='community'&&location.pathname.startsWith('/community'))history.pushState({},'', '/');state.route=route;if(route==='community'&&!location.pathname.startsWith('/community'))history.pushState({community:true},'','/community');persist();render();if(route!=='talk-to-mira')window.scrollTo({top:0,behavior:'smooth'});}
export function view(mode){auth.mode=mode;render();window.scrollTo(0,0)}

